def cards(text,prefix):
 matches=list(re.finditer(r'^### ('+prefix+r'-\d+(?:\.R\d+)?) —[^\n]+',text,re.M));out={}
 for i,m in enumerate(matches):
  block=text[m.end():matches[i+1].start() if i+1<len(matches) else len(text)]
  out[m.group(1)]={'title':m.group(0),'dependencies':re.search(r'\*\*Depende de:\*\* ([^\n]+)',block).group(1).split(' **')[0]}
 return out
for name,prefix,n in [('docs/PLANO-DE-IMPLEMENTACAO.md','M[01]',41),('docs/ROTEIRO-V1.md','V1',6)]:
 current=cards(read(name),prefix);assert len(current)==n and current==cards(old(name),prefix)
def states(t):return dict(re.findall(r'^\| (M[01]-\d+(?:\.R\d+)?) \| [^|]+ \| ([^|]+?) \|',t,re.M))
