links=0
for name in files:
 for target in re.findall(r'\[[^\]]*\]\(([^)]+)\)',read(name)):
  target=target.strip('<>')
  if re.match(r'^[a-zA-Z]+:',target) or target.startswith('#'):continue
  p=(root/name).parent/unquote(target.split('#')[0]);assert p.exists() or p.resolve()==(root/output).resolve(),(name,target);links+=1
